\voffset=-.4in

%the next gives two direction arrows at the top of a 2 x 2 matrix

\newcommand{\directs}[2]{\def\objectstyle{\scriptstyle} \objectmargin={0pt}
\xy
(0,4)*+{}="a",(0,-2)*+{\rule{0em}{1.5ex}#2}="b",(7,4)*+{\;#1}="c"
\ar@{->} "a";"b" \ar @{->}"a";"c" \endxy }

\theoremstyle{plain}
